<?phpnamespace app\store\controller;use app\store\model\Setting as SettingModel;use hema\map\Driver as MapDriver;use think\facade\View;/** * 站点配置 */class Setting extends Controller{	/**     * 基础设置     */    public function base()    {        return $this->updateEvent('base');    }        /**     * 地图设置     */    public function map()    {        $map = new MapDriver;        $list = $map->company();        View::assign('list',$list);        return $this->updateEvent('map');    }    /**     * 更新设置事件     */    private function updateEvent(string $key)    {        if (!$this->request->isAjax()) {            $model = SettingModel::getItem($key);            return View::fetch($key, compact('model'));        }        $model = new SettingModel;        if ($model->edit($key,$this->postData('data'))) {            return $this->renderSuccess('更新成功');        }        $error = $model->getError() ?: '更新失败';        return $this->renderError($error);    }}